<style>
.swe-home{--wine:#641b2a;--cream:#faf7f2;--gold:#b78a54;--ink:#35252a;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif;padding-top:64px}.swe-home *{box-sizing:border-box}.swe-home [hidden]{display:none!important}.swe-home a:focus-visible{outline:3px solid #b78a54;outline-offset:6px}.swe-wrap{width:min(1200px,calc(100% - 64px));margin-inline:auto}.swe-home h1,.swe-home h2,.swe-location h3,.swe-empty h3{font-family:'Playfair Display',Georgia,serif;font-weight:400;letter-spacing:-.045em}.swe-home h2{font-size:clamp(32px,3.8vw,52px);line-height:1.15;margin:14px 0 24px}.swe-home em{font-weight:400;color:var(--wine)}.swe-eyebrow{display:block;font-size:10px;font-weight:700;letter-spacing:.2em;line-height:1.8;color:var(--wine)}.swe-light{color:#e6c7a2}.swe-hero{position:relative;isolation:isolate;background:#3c1720;color:#fff;overflow:hidden}.swe-hero-photo{position:absolute;inset:0;z-index:-2}.swe-hero-photo img{width:100%;height:100%;object-fit:cover;object-position:center 45%}.swe-hero:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(43,13,23,.94),rgba(56,17,29,.68) 48%,rgba(38,16,20,.12)),linear-gradient(0deg,rgba(38,13,21,.72),transparent 40%);z-index:-1}.swe-hero-inner{min-height:650px;display:flex;align-items:center;justify-content:space-between;gap:60px;padding-block:70px 54px}.swe-hero-copy{max-width:690px}.swe-event-name{font-size:15px;margin:24px 0 12px;color:#f0dcca}.swe-hero h1{font-size:clamp(46px,5.7vw,80px);line-height:1.07;margin:0 0 22px}.swe-hero h1 em{color:#edcda9}.swe-hero-description{max-width:490px;font-size:15px;line-height:1.9;color:#f4e8e4}.swe-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:30px}.swe-btn{display:inline-flex;align-items:center;justify-content:center;gap:32px;min-height:48px;padding:14px 23px;font-size:13px;font-weight:600;border:1px solid transparent;border-radius:4px;transition:background .2s,transform .2s}.swe-btn:hover{transform:translateY(-2px)}.swe-btn-cream{ba