ze:13px;color:#796969;line-height:1.9;margin-bottom:20px}.swe-schedule-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:60px}.swe-agenda-row{display:flex;align-items:center;gap:28px;padding:24px 0;border-top:1px solid #ddcfc1}.swe-date{min-width:75px;display:flex;flex-direction:column;align-items:center;color:var(--wine)}.swe-date strong{font-family:Georgia,serif;font-size:42px;font-weight:400;line-height:1.1}.swe-date span{font-size:10px;margin-top:7px}.swe-agenda-row .swe-eyebrow{font-size:9px;letter-spacing:.1em}.swe-agenda-row h3{font-size:15px;font-weight:500;margin:8px 0;line-height:1.6}.swe-agenda-row p{font-size:12px;color:#796969}.swe-location{padding:30px;background:#eee4da}.swe-location h3{font-size:30px;line-height:1.25;margin:12px 0}.swe-location p{font-size:12px;color:#796969;line-height:1.8;margin-bottom:22px}.swe-location iframe{width:100%;height:190px;border:0;margin-top:25px}.swe-memories{background:#fff}.swe-video-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.swe-video-grid iframe{width:100%;aspect-ratio:16/9;border:0;background:#2d1820}.swe-video-grid h3{font-size:12px;font-weight:500;margin-top:14px}.swe-memory-banner{min-height:230px;background:#4e2832;padding:45px;display:flex;align-items:center}.swe-memory-banner p{font-family:'Playfair Display',Georgia,serif;font-size:30px;color:#f9e9d7;max-width:620px;line-height:1.4;margin-bottom:22px}.swe-sponsors{text-align:center;padding-block:55px}.swe-sponsors h2{font-size:32px}.swe-sponsor-grid{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:28px;margin-top:30px}.swe-sponsor-grid img{width:140px;height:85px;object-fit:contain}.swe-exhibitor{background:var(--wine);color:#fff;position:relative;overflow:hidden}.swe-exhibitor:before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 28px,#ffffff04 28px,#ffffff04 29px);pointer-events:none}.swe-exhibitor-inner{display:flex;align-items:center;just